-- Life Radar cell (radar), generated by cellkit.sqlgen from cell.yaml.
-- Every row belongs to a workspace and is visible only while the transaction
-- is bound to it (app.workspace_id). Do not edit once applied; add a new migration.

CREATE SCHEMA radar;

CREATE FUNCTION radar.current_workspace() RETURNS uuid
LANGUAGE sql STABLE AS $$
    SELECT nullif(current_setting('app.workspace_id', true), '')::uuid
$$;

CREATE TABLE radar.opportunities (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    slug                     text NOT NULL CHECK (length(slug) <= 120 AND length(slug) >= 1),
    name                     text NOT NULL CHECK (length(name) <= 300 AND length(name) >= 1),
    name_th                  text CHECK (name_th IS NULL OR (length(name_th) <= 300)),
    description              text,
    category                 text NOT NULL CHECK (length(category) <= 200 AND length(category) >= 1),
    country                  text CHECK (country IS NULL OR (length(country) <= 8)),
    region                   text,
    issuer                   text,
    official_url             text,
    value_benefit            text,
    cost                     text,
    nationalities            jsonb CHECK (nationalities IS NULL OR (jsonb_typeof(nationalities) = 'array')),
    thai_eligible            text NOT NULL DEFAULT 'unknown' CHECK (thai_eligible IN ('yes', 'no', 'partial', 'unknown')),
    min_age                  integer CHECK (min_age IS NULL OR (min_age >= 0 AND min_age <= 120)),
    max_age                  integer CHECK (max_age IS NULL OR (max_age >= 0 AND max_age <= 120)),
    age_basis                text NOT NULL DEFAULT 'unspecified' CHECK (age_basis IN ('at_application', 'at_start', 'at_deadline', 'calendar_year', 'unspecified')),
    gender                   text NOT NULL DEFAULT 'any' CHECK (gender IN ('any', 'male', 'female')),
    min_education            text NOT NULL DEFAULT 'none' CHECK (min_education IN ('none', 'secondary', 'vocational', 'bachelor', 'master', 'doctorate')),
    enrollment_required      jsonb CHECK (enrollment_required IS NULL OR (jsonb_typeof(enrollment_required) = 'array')),
    education_text           text,
    profession               text,
    conditions_text          text,
    conditions               jsonb CHECK (conditions IS NULL OR (jsonb_typeof(conditions) = 'object')),
    recurrence               text NOT NULL DEFAULT 'annual' CHECK (recurrence IN ('rolling', 'annual', 'one_off', 'cohort')),
    open_date                date,
    close_date               date,
    window_months            jsonb CHECK (window_months IS NULL OR (jsonb_typeof(window_months) = 'array')),
    quota                    text,
    attempts_limit           integer CHECK (attempts_limit IS NULL OR (attempts_limit >= 1)),
    prep_lead_time_months    integer NOT NULL DEFAULT 0 CHECK (prep_lead_time_months >= 0 AND prep_lead_time_months <= 240),
    prerequisites            jsonb CHECK (prerequisites IS NULL OR (jsonb_typeof(prerequisites) = 'array')),
    urgency                  text NOT NULL DEFAULT 'evergreen' CHECK (urgency IN ('time_critical', 'preparation_critical', 'evergreen')),
    source_url               text,
    last_verified_at         date,
    verification_status      text NOT NULL DEFAULT 'unverified' CHECK (verification_status IN ('verified', 'partially_verified', 'unverified', 'stale')),
    verification_notes       text,
    status                   text NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended', 'discontinued')),
    tags                     jsonb CHECK (tags IS NULL OR (jsonb_typeof(tags) = 'array')),
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, slug)
);
CREATE UNIQUE INDEX opportunities_legacy ON radar.opportunities (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX opportunities_category ON radar.opportunities (workspace_id, category);
CREATE INDEX opportunities_country ON radar.opportunities (workspace_id, country);
CREATE INDEX opportunities_recurrence ON radar.opportunities (workspace_id, recurrence);
CREATE INDEX opportunities_status ON radar.opportunities (workspace_id, status);
CREATE INDEX opportunities_thai_eligible ON radar.opportunities (workspace_id, thai_eligible);
CREATE INDEX opportunities_urgency ON radar.opportunities (workspace_id, urgency);
CREATE INDEX opportunities_verification_status ON radar.opportunities (workspace_id, verification_status);

CREATE TABLE radar.profiles (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    display_name             text NOT NULL CHECK (length(display_name) <= 200 AND length(display_name) >= 1),
    birthdate                date NOT NULL,
    nationality              text NOT NULL CHECK (length(nationality) <= 2 AND length(nationality) >= 1),
    other_nationalities      jsonb CHECK (other_nationalities IS NULL OR (jsonb_typeof(other_nationalities) = 'array')),
    gender                   text NOT NULL DEFAULT 'unspecified' CHECK (gender IN ('unspecified', 'male', 'female', 'other')),
    education_level          text NOT NULL DEFAULT 'none' CHECK (education_level IN ('none', 'secondary', 'vocational', 'bachelor', 'master', 'doctorate')),
    enrolled_in              text NOT NULL DEFAULT 'none' CHECK (enrolled_in IN ('none', 'secondary', 'vocational', 'bachelor', 'master', 'doctorate')),
    profession               text,
    country_of_residence     text CHECK (country_of_residence IS NULL OR (length(country_of_residence) <= 2)),
    interests                jsonb CHECK (interests IS NULL OR (jsonb_typeof(interests) = 'array')),
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id)
);
CREATE UNIQUE INDEX profiles_legacy ON radar.profiles (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;

CREATE TABLE radar.opportunity_statuses (
    workspace_id             uuid NOT NULL,
    id                       bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 1000000),
    legacy_id                bigint,
    profile_id               bigint NOT NULL,
    opportunity_id           bigint NOT NULL,
    status                   text NOT NULL DEFAULT 'interested' CHECK (status IN ('interested', 'preparing', 'applied', 'accepted', 'rejected', 'missed', 'not_eligible', 'dismissed')),
    target_cycle             text CHECK (target_cycle IS NULL OR (length(target_cycle) <= 50)),
    next_action              text,
    next_action_on           date,
    notes                    text,
    version                  bigint NOT NULL DEFAULT 1,
    created_at               timestamptz NOT NULL DEFAULT now(),
    updated_at               timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, id),
    UNIQUE (workspace_id, profile_id, opportunity_id),
    FOREIGN KEY (workspace_id, profile_id) REFERENCES radar.profiles (workspace_id, id),
    FOREIGN KEY (workspace_id, opportunity_id) REFERENCES radar.opportunities (workspace_id, id)
);
CREATE UNIQUE INDEX opportunity_statuses_legacy ON radar.opportunity_statuses (workspace_id, legacy_id) WHERE legacy_id IS NOT NULL;
CREATE INDEX opportunity_statuses_opportunity_id ON radar.opportunity_statuses (workspace_id, opportunity_id);
CREATE INDEX opportunity_statuses_profile_id ON radar.opportunity_statuses (workspace_id, profile_id);
CREATE INDEX opportunity_statuses_status ON radar.opportunity_statuses (workspace_id, status);

-- Idempotent creates: a key reserves the record id before the platform execution starts.
CREATE TABLE radar.create_keys (
    workspace_id uuid NOT NULL,
    actor        uuid NOT NULL,
    kind         text NOT NULL CHECK (kind IN ('opportunity', 'profile', 'opportunity-status')),
    key          text NOT NULL CHECK (length(key) BETWEEN 8 AND 200),
    record_id    bigint NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (workspace_id, actor, kind, key)
);

-- Graph events, written in the same transaction as the change (at-least-once delivery).
CREATE TABLE radar.outbox (
    id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    workspace_id    uuid NOT NULL,
    type            text NOT NULL,
    subject         text NOT NULL,
    execution_id    uuid,
    classification  text NOT NULL DEFAULT 'confidential',
    payload         jsonb NOT NULL,
    occurred_at     timestamptz NOT NULL DEFAULT now(),
    published_at    timestamptz,
    attempts        integer NOT NULL DEFAULT 0,
    next_attempt_at timestamptz NOT NULL DEFAULT now(),
    last_error      text,
    correlation_id  text
);
CREATE INDEX outbox_pending ON radar.outbox (next_attempt_at) WHERE published_at IS NULL;

DO $$
DECLARE
    t text;
BEGIN
    FOREACH t IN ARRAY ARRAY['opportunities', 'profiles', 'opportunity_statuses', 'create_keys', 'outbox'] LOOP
        EXECUTE format('ALTER TABLE radar.%I ENABLE ROW LEVEL SECURITY', t);
        EXECUTE format('ALTER TABLE radar.%I FORCE ROW LEVEL SECURITY', t);
        EXECUTE format('CREATE POLICY workspace_isolation ON radar.%I'
                       ' USING (workspace_id = radar.current_workspace())'
                       ' WITH CHECK (workspace_id = radar.current_workspace())', t);
    END LOOP;
END
$$;

GRANT USAGE ON SCHEMA radar TO radar_api;
GRANT EXECUTE ON FUNCTION radar.current_workspace() TO radar_api;
GRANT SELECT, INSERT, UPDATE, DELETE ON radar.opportunities, radar.profiles, radar.opportunity_statuses TO radar_api;
GRANT USAGE ON SEQUENCE radar.opportunities_id_seq, radar.profiles_id_seq, radar.opportunity_statuses_id_seq TO radar_api;
GRANT SELECT, INSERT ON radar.create_keys TO radar_api;
GRANT SELECT, INSERT ON radar.outbox TO radar_api;
GRANT UPDATE (execution_id, published_at, attempts, next_attempt_at, last_error) ON radar.outbox TO radar_api;

-- The publisher sweeps the outbox of one workspace per token; it reads past RLS for the outbox only.
CREATE POLICY publisher_sweep ON radar.outbox TO radar_publisher USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA radar TO radar_publisher;
GRANT SELECT ON radar.outbox TO radar_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON radar.outbox TO radar_publisher;
GRANT UPDATE (published_at, attempts, next_attempt_at, last_error) ON radar.outbox TO radar_publisher;
-- Life Radar rules beyond the generated columns.
ALTER TABLE radar.opportunities
    ADD CONSTRAINT opportunities_age_range CHECK (min_age IS NULL OR max_age IS NULL OR min_age <= max_age),
    ADD CONSTRAINT opportunities_window CHECK (open_date IS NULL OR close_date IS NULL OR open_date <= close_date),
    ADD CONSTRAINT opportunities_category_path CHECK (category ~ '^[a-z0-9]+(-[a-z0-9]+)*(/[a-z0-9]+(-[a-z0-9]+)*)*$'),
    ADD CONSTRAINT opportunities_slug_format CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$');
-- Category prefix queries (category = 'abroad' OR category LIKE 'abroad/%').
CREATE INDEX opportunities_category_prefix ON radar.opportunities (workspace_id, category text_pattern_ops);
